def semver_sort(versions):
    def parse(v):
        core_and_pre = v.split('+', 1)[0]
        if '-' in core_and_pre:
            core, pre = core_and_pre.split('-', 1)
            has_pre = True
        else:
            core = core_and_pre
            pre = ''
            has_pre = False
        major, minor, patch = (int(x) for x in core.split('.'))
        if has_pre:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
        else:
            pre_key = []
        flag = 1 if not has_pre else 0
        return (major, minor, patch, flag, pre_key)

    return sorted(versions, key=parse)

